<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Gallery; use App\Models\GalleryImage; use Illuminate\Http\Request; use Illuminate\Support\Str;
class GalleryController extends Controller { public function index(){return view('admin.gallery.index',['galleries'=>Gallery::with('images')->latest()->paginate(12)]);} public function store(Request $r){$d=$r->validate(['title'=>'required|max:180','description'=>'nullable','cover_image'=>'nullable|image|max:4096']);$d['slug']=Str::slug($d['title']).'-'.Str::lower(Str::random(5));if($r->hasFile('cover_image'))$d['cover_image']=$r->file('cover_image')->store('galleries','public');Gallery::create($d);return back()->with('success','Gallery created.');} public function upload(Request $r,Gallery $gallery){$d=$r->validate(['image'=>'required|image|max:6144','caption'=>'nullable|max:255','published'=>'nullable|boolean']);$d['gallery_id']=$gallery->id;$d['path']=$r->file('image')->store('gallery','public');GalleryImage::create($d);return back()->with('success','Image uploaded.');} public function destroyImage(GalleryImage $image){$image->delete();return back()->with('success','Image removed.');} }
